
import type { Image } from './Image.js';
import type { InventoryRoutingSourceRequest } from './InventoryRoutingSourceRequest.js';
import type { MoneyValue } from './MoneyValue.js';
import type { SubscriptionDeliveryMethodCounts } from './SubscriptionDeliveryMethodCounts.js';
import type { SubscriptionIntervalOption } from './SubscriptionIntervalOption.js';
import type { SubscriptionPlanLineItem } from './SubscriptionPlanLineItem.js';

export type SubscriptionPlan = { "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Format: int32. */ "billing_interval_count": number; /** maxItems: 12. */ "billing_interval_options": Array<SubscriptionIntervalOption>; /** Format: int32. */ "contract_term_months"?: number; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "delivery_method_subscription_counts": Array<SubscriptionDeliveryMethodCounts>; "delivery_required": boolean; "description"?: string; "early_termination_fee_money"?: MoneyValue; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "images": Array<Image>; /** Where tracked demand from this plan is routed. New subscriptions and payment links for the plan copy it. Absent when the plan has no source. */ "inventory_routing_source"?: InventoryRoutingSourceRequest; "line_items"?: Array<SubscriptionPlanLineItem>; "merchant_id"?: string; "metadata"?: Record<string, string>; "name": string; /** maxItems: 10. */ "quantity_options": Array<number>; "setup_fee_money"?: MoneyValue; "status": "active" | "archived" | (string & {}); "subscription_delivery_method_ids": Array<string>; "subscription_plan_id": string; /** Format: int32. */ "trial_period_days"?: number; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; };
